(x, y, t) => {
  const cx = 240, cy = 120;
  const wells = [
    [160+Math.sin(t*0.4)*120, 80+Math.cos(t*0.3)*60, 8000, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.6)*70, 6000, 0.1, 1.7],
    [240+Math.sin(t*0.25+2)*160, 120+Math.cos(t*0.45+1)*100, 10000, 0.06, 2.5],
    [100+Math.cos(t*0.7+1)*90, 190+Math.sin(t*0.5+3)*70, 5000, 0.12, 1.4],
    [380+Math.sin(t*0.35+4)*100, 50+Math.cos(t*0.8+2)*80, 7000, 0.07, 2.8],
    [240+Math.cos(t*0.3+5)*130, 210+Math.sin(t*0.5)*90, 9000, 0.09, 2.1],
    [60+Math.sin(t*0.55+3)*70, 40+Math.cos(t*0.65)*50, 4000, 0.14, 1.6],
    [420+Math.cos(t*0.45+2)*80, 200+Math.sin(t*0.75+1)*60, 5500, 0.11, 1.9]
  ];
  let gx = 0, gy = 0, potential = 0;
  for (const [wX, wY, mass, f, sp] of wells) {
    const dx = x - wX, dy = y - wY;
    const dist2 = dx*dx + dy*dy + 1;
    const dist = Math.sqrt(dist2);
    const pull = mass / dist2;
    gx -= dx / dist * pull * 0.15;
    gy -= dy / dist * pull * 0.15;
    potential += Math.sin(dist * f - t * sp) * Math.min(1, pull * 0.08);
  }
  const flow = Math.sin(x*0.018+t*0.4)*Math.cos(y*0.022-t*0.3)*20 + Math.sin((x+y)*0.01+t*0.5)*15;
  const flory = Math.cos(x*0.02-t*0.35)*Math.sin(y*0.016+t*0.45)*18;
  const sx = x + gx + flow, sy = y + gy + flory;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.09, 2.2],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.11, 1.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.07, 2.6],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.13, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.08, 3.0],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.1, 2.1]
  ];
  let aS = 0, iS = 0, kE = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const wave = Math.sin(d*f - t*sp);
    aS += wave;
    iS += Math.sin(d*f*0.6 + t*sp*0.5 + 2.0);
    kE += wave * Math.max(0, 1 - d * 0.003);
  }
  const act = aS/6, inh = iS/6, kinetic = kE/6;
  const bg = (Math.sin(sx*0.035+sy*0.02+t*0.9) + Math.sin(sx*0.028-sy*0.035+t*1.3))/2 + Math.sin((sx+sy)*0.1+t*2.8)*0.25 + Math.sin((sx-sy)*0.08-t*2.2)*0.25;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.045-ang*4-t*1.8) + Math.sin(dist*0.035+ang*5-t*1.4))*0.35;
  const voronoi = Math.min(...wells.map(([wX,wY]) => Math.sqrt((sx-wX)**2+(sy-wY)**2)));
  const cellEdge = Math.abs(Math.sin(voronoi*0.15 + t*0.5)) * 0.4;
  const energy = potential * 0.3 + Math.abs(kinetic) * 0.7;
  const reaction = Math.tanh((act - inh*0.65 + bg*0.25 + spiral + cellEdge)*2.8);
  const conservation = Math.tanh((reaction + energy*0.4 - 0.1)*1.8);
  const v = conservation*0.5+0.5;
  const pal = [
    [2,4,15],[5,15,60],[10,40,120],[0,140,180],
    [0,255,200],[80,255,100],[255,255,0],
    [255,140,0],[255,40,40],[255,0,120],[180,0,255],[80,0,180],[2,4,15]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.7 + Math.abs(conservation)*0.5;
  const glow = Math.max(0, conservation - 0.3) * 2.5;
  const neon = Math.max(0, Math.abs(conservation) - 0.5) * 3;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum + glow*40 + neon*pal[i][0]*0.5))|0,
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum + glow*60 + neon*pal[i][1]*0.5))|0,
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum + glow*80 + neon*pal[i][2]*0.5))|0
  ];
}
